package pt.qpetiscos.agenda;
import android.app.*;import android.appwidget.*;import android.os.*;import android.content.*;import android.widget.*;
public class WidgetSettings extends Activity {public void onCreate(Bundle b){super.onCreate(b);int id=getIntent().getIntExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,-1);setResult(RESULT_CANCELED);if(id<0){finish();return;}LinearLayout l=new LinearLayout(this);l.setOrientation(1);l.setPadding(32,32,32,32);TextView t=new TextView(this);t.setText("Fundo do widget QPetiscos");l.addView(t);String[] names={"Branco","Castanho escuro","Transparente"};for(int i=0;i<3;i++){final int theme=i;Button x=new Button(this);x.setText(names[i]);l.addView(x);x.setOnClickListener(v->{getSharedPreferences("widget_theme",0).edit().putInt("theme"+id,theme).apply();WidgetAgenda.refreshAll(this);WidgetAgenda.schedule(this);Intent result=new Intent().putExtra(AppWidgetManager.EXTRA_APPWIDGET_ID,id);setResult(RESULT_OK,result);finish();});}setContentView(l);}}
